# ----------------------------------------------------------------------------------------------------------
# Samples with joint margins
# ----------------------------------------------------------------------------------------------------------
def margin_of(Q, lo, hi):
    return np.minimum(Q - lo, hi - Q).min(axis=-1)


def usable_samples(model, side, n_samples, seed):
    chain = S.arm_chain(model, side)
    jnt = arm_ids(model, side)["jnt"]
    lo, hi = model.jnt_range[jnt, 0], model.jnt_range[jnt, 1]
    sc = SEARCH_CFG
    key = f"{n_samples}_{seed}_{sc['approach_down_deg']}_{sc['approach_cone_deg']}_{sc['finger_axis_max_z']}"
    cache = PROJECT_ROOT / "data" / "beaker_hotplate_staging" / f"layout_samples_{side}_{key}.npz"
    if cache.exists():
        z = np.load(cache)
        return z["P"], z["Q"], z["M"], lo, hi, chain
    rng = np.random.default_rng(seed)
    a_nom = np.array([math.cos(sc["approach_down_deg"] * DEG), 0.0, -math.sin(sc["approach_down_deg"] * DEG)])
    cos_cone = math.cos(sc["approach_cone_deg"] * DEG)
    P, Qs, done = [], [], 0
    while done < n_samples:
        Q = rng.uniform(lo, hi, (250_000, 7))
        p, R = S.batch_fk(chain, Q)
        keep = (R[:, :, 2] @ a_nom >= cos_cone) & (np.abs(R[:, 2, 1]) <= sc["finger_axis_max_z"])
        P.append(p[keep])
        Qs.append(Q[keep])
        done += 250_000
    P, Q = np.concatenate(P), np.concatenate(Qs)
    M = margin_of(Q, lo, hi)
    cache.parent.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(cache, P=P, Q=Q, M=M)
    return P, Q, M, lo, hi, chain


# ----------------------------------------------------------------------------------------------------------
# Vectorised IK (position hard, gripper orientation soft near its limits), many seeds at once
# ----------------------------------------------------------------------------------------------------------
A_NOM = np.array([math.cos(SEARCH_CFG["approach_down_deg"] * DEG), 0.0, -math.sin(SEARCH_CFG["approach_down_deg"] * DEG)])
CONE = SEARCH_CFG["approach_cone_deg"] * DEG
YMAX = SEARCH_CFG["finger_axis_max_z"]


def _resid(chain, Q, p_t):
    p, R = S.batch_fk(chain, Q)
    ang = np.arccos(np.clip(R[:, :, 2] @ A_NOM, -1, 1))
    return np.c_[p - p_t, np.maximum(0.0, ang - 0.8 * CONE), np.maximum(0.0, np.abs(R[:, 2, 1]) - 0.8 * YMAX)]


def batch_ik(chain, Q0, lo, hi, p_t, iters=60, lam=0.02, eps=1e-6):
    q = np.clip(Q0, lo, hi)
    N = len(q)
    eye = np.eye(5)
    for _ in range(iters):
        Qp = np.repeat(q[:, None, :], 8, axis=1)
        for j in range(7):
            Qp[:, 1 + j, j] += eps
        Rall = _resid(chain, Qp.reshape(-1, 7), p_t).reshape(N, 8, 5)
        r = Rall[:, 0]
        J = ((Rall[:, 1:] - r[:, None, :]) / eps).transpose(0, 2, 1)           # (N, 5, 7)
        y = np.linalg.solve(J @ J.transpose(0, 2, 1) + lam ** 2 * eye, r[..., None])[..., 0]
        dq = -(J.transpose(0, 2, 1) @ y[..., None])[..., 0]
        n = np.abs(dq).max(axis=1, keepdims=True)
        q = np.clip(q + dq * np.minimum(1.0, 0.3 / np.maximum(n, 1e-12)), lo, hi)
    return q


def accepted(chain, q, p_t, tol=1e-3):
    p, R = S.batch_fk(chain, q)
    return (np.linalg.norm(p - p_t, axis=1) < tol) & (R[:, :, 2] @ A_NOM >= math.cos(CONE)) & (np.abs(R[:, 2, 1]) <= YMAX)


# ----------------------------------------------------------------------------------------------------------
# Scene context: placing things and checking contacts
# ----------------------------------------------------------------------------------------------------------
class Ctx(dict):
    """Plain dict with attribute access; holds the model, data and the geom lists for the contact checks."""
    __getattr__ = dict.__getitem__


def make_ctx(sim, side, z_rest):
    model, data = sim.model, sim.data
    root = model.body("base_link").id
    under = lambda b: S._is_under(model, int(b), root)
    ids = arm_ids(model, side)
    moving = {b for b in range(model.nbody) if model.body(b).name.startswith(f"openarm_{side}_") and not model.body(b).name.endswith("link0")}
    arm_g = [g for g in range(model.ngeom) if model.geom_bodyid[g] in moving and model.geom_group[g] == 3]
    finger_g = {g for g in arm_g if "finger" in model.body(model.geom_bodyid[g]).name}
    beaker, hot = model.body("task_beaker").id, model.body("task_hotplate").id
    static_other = [g for g in range(model.ngeom) if model.geom_bodyid[g] not in (0, beaker, hot) and not under(model.geom_bodyid[g])
                    and (model.geom_contype[g] or model.geom_conaffinity[g])]
    return Ctx(model=model, data=data, ids=ids, moving=moving, arm_g=arm_g, finger_g=finger_g, root=root, under=under, z_rest=z_rest,
               beaker_g=model.geom("task_beaker_glass").id, plate_g=model.geom("task_hotplate_top_plate").id,
               hotbase_g=model.geom("task_hotplate_base").id, hot_body=hot, static_other=static_other,
               beaker_free=int(model.joint("task_beaker_free").qposadr[0]), top=bench_top_z(model),
               ped_adr=[int(model.joint(j).qposadr[0]) for j in robot_specs.PEDESTAL_SPECS["joints"]],
               finger_adr=[int(model.jnt_qposadr[model.actuator_trnid[a, 0]]) for a in ids["fingers"]])


def set_scene(ctx, base_xy, yaw, ped_q, q_arm, finger_q, beaker_origin, hotplate_xy):
    m, d = ctx.model, ctx.data
    d.qpos[0:7] = [base_xy[0], base_xy[1], ctx.z_rest, *yaw_to_quat(yaw)]
    for a in ctx.ped_adr:
        d.qpos[a] = ped_q
    for a, v in zip(ctx.ids["qadr"], q_arm):
        d.qpos[a] = v
    for a in ctx.finger_adr:
        d.qpos[a] = finger_q
    d.qpos[ctx.beaker_free:ctx.beaker_free + 7] = [*beaker_origin, 1, 0, 0, 0]
    m.body_pos[ctx.hot_body] = [hotplate_xy[0], hotplate_xy[1], ctx.top]
    mujoco.mj_kinematics(m, d)
    mujoco.mj_comPos(m, d)
    mujoco.mj_collision(m, d)


def is_clear(ctx, margin, held=False, setdown=False):
    """No contact: arm geoms >= margin from everything (fingers may touch the beaker); the held beaker >= margin from
    everything but (set-down) the hotplate it rests on; no self-collision of the arm."""
    m, d = ctx.model, ctx.data
    ft = np.zeros(6)
    base = d.xpos[ctx.root]
    near = [g for g in ctx.static_other if np.linalg.norm(d.geom_xpos[g] - base) < 1.6]
    for g in ctx.arm_g:
        others = near + [ctx.plate_g, ctx.hotbase_g] + ([] if g in ctx.finger_g else [ctx.beaker_g])
        for o in others:
            if mujoco.mj_geomDistance(m, d, g, o, margin, ft) < margin:
                return False
    if held:
        for o in near + ([] if setdown else [ctx.plate_g, ctx.hotbase_g]):
            if mujoco.mj_geomDistance(m, d, ctx.beaker_g, o, margin, ft) < margin:
                return False
        if setdown and mujoco.mj_geomDistance(m, d, ctx.beaker_g, ctx.hotbase_g, margin, ft) < 0:
            return False
    for i in range(d.ncon):
        c = d.contact[i]
        b1, b2 = int(m.geom_bodyid[c.geom1]), int(m.geom_bodyid[c.geom2])
        if c.dist < 0 and 0 not in (b1, b2) and (b1 in ctx.moving or b2 in ctx.moving) and ctx.under(b1) and ctx.under(b2):
            return False
    return True


# ----------------------------------------------------------------------------------------------------------
# Task geometry
# ----------------------------------------------------------------------------------------------------------
class Geo:
    def __init__(self, model):
        self.top = bench_top_z(model)
        bg = model.geom("bench_top")
        self.bench_hx, self.bench_hy = float(model.geom_size[bg.id][0]), float(model.geom_size[bg.id][1])
        self.beaker_h = 2 * float(model.geom_size[model.geom("task_beaker_glass").id][1])
        self.beaker_r = float(model.geom_size[model.geom("task_beaker_glass").id][0])
        self.plate_top = self.top + float(model.site_pos[model.site("hotplate_top").id][2])
        self.hot_half_y = float(model.geom_size[model.geom("task_hotplate_base").id][1])
        self.hot_half_x = float(model.geom_size[model.geom("task_hotplate_base").id][0])
        self.pair_y = self.bench_hy - C["bench_edge_margin"] - self.hot_half_y


def task_points(g, beaker_xy, hotplate_xy, yaw):
    """World TCP targets of the four task poses for this layout and facing direction."""
    bxy, hxy = np.asarray(beaker_xy), np.asarray(hotplate_xy)
    fwd = np.array([math.cos(yaw), math.sin(yaw)])
    return {
        "grasp": np.r_[bxy, g.top + SEARCH_CFG["grasp_height_frac"] * g.beaker_h],
        "above_plate": np.r_[hxy, g.plate_top + SEARCH_CFG["place_clear_above_plate"]],
        "setdown": np.r_[hxy, g.plate_top + C["setdown_clearance"] + 0.5 * g.beaker_h],
        "ready": np.r_[bxy - SEARCH_CFG["ready_back_off"] * fwd, g.top + g.beaker_h + SEARCH_CFG["ready_clear_above_top"]],
    }


def to_body(pw, base_xy, yaw, body_z):
    c, s = math.cos(yaw), math.sin(yaw)
    dx, dy = pw[0] - base_xy[0], pw[1] - base_xy[1]
    return np.array([c * dx + s * dy, -s * dx + c * dy, pw[2] - body_z])


def pose_scene_args(g, name, beaker_xy, tcp):
    """finger opening and where the beaker is for each pose: held in the hand for above_plate / setdown."""
    if name in ("above_plate", "setdown"):
        return C["holding_finger_q"], np.array([tcp[0], tcp[1], tcp[2] - 0.5 * g.beaker_h]), True
    return SEARCH_CFG["finger_open"], np.array([beaker_xy[0], beaker_xy[1], g.top + 0.002]), False


# ----------------------------------------------------------------------------------------------------------
# Exact solve of one task pose: largest joint margin with a collision-free IK solution
# ----------------------------------------------------------------------------------------------------------
class Arm:
    def __init__(self, P, Q, M, lo, hi, chain):
        self.P, self.Q, self.M, self.lo, self.hi, self.chain = P, Q, M, lo, hi, chain
        self.tree = cKDTree(P)


def solve_pose(arm, ctx, g, name, layout, base_xy, yaw, ped_q, extra_seeds=None, floor=0.0, upper=0.7, probe=None, strict=False):
    """Largest margin m (rad) such that an IK solution with all joints >= m from their limits exists at this task point,
    is accepted (position < 1 mm, gripper orientation inside its limits) and is collision-free. Bisection on m.
    probe: test this margin first (the requirement). Returns dict(margin, q, tried_ok_at_probe)."""
    pts = task_points(g, layout["beaker_xy"], layout["hotplate_xy"], yaw)
    tcp = pts[name]
    body_z = ctx.z_rest + 0.75 + 2 * ped_q
    p_t = to_body(tcp, base_xy, yaw, body_z)
    finger_q, beaker_origin, held = pose_scene_args(g, name, layout["beaker_xy"], tcp)
    _, idx = arm.tree.query(p_t, k=C["n_seeds"] * 3)
    seeds = arm.Q[np.atleast_1d(idx)]
    seeds = seeds[np.argsort(-arm.M[np.atleast_1d(idx)])][:C["n_seeds"]]
    if extra_seeds is not None:
        seeds = np.vstack([extra_seeds, seeds])

    def attempt(m):
        qs = batch_ik(arm.chain, seeds, arm.lo + m, arm.hi - m, p_t)
        ok = accepted(arm.chain, qs, p_t)
        if not ok.any():
            return None
        qs = qs[ok]
        mg = margin_of(qs, arm.lo, arm.hi)
        order = np.argsort(-mg)
        tried = 0
        last = None
        for i in order:
            if last is not None and np.abs(qs[i] - last).max() < 0.02:
                continue                                              # near-duplicate of one that failed
            last = qs[i]
            tried += 1
            set_scene(ctx, base_xy, yaw, ped_q, qs[i], finger_q, beaker_origin, layout["hotplate_xy"])
            if is_clear(ctx, C["clear_margin"], held=held, setdown=(name == "setdown")):
                return qs[i], float(mg[i])
            if tried >= 6:
                break
        return None

    best = None
    lo_m, hi_m = floor, upper
    if probe is not None:
        r = attempt(probe)
        if r is not None:
            best, lo_m = r, max(probe, r[1])
        else:
            hi_m = probe
            if strict:
                return dict(margin=None, q=None, tcp=tcp, p_body=p_t)
    else:
        r = attempt(lo_m)
        if r is None:
            return dict(margin=None, q=None, tcp=tcp, p_body=p_t)
        best = r
        lo_m = max(lo_m, r[1])
    for _ in range(7):
        mid = 0.5 * (lo_m + hi_m)
        if hi_m - lo_m < 0.004:
            break
        r = attempt(mid)
        if r is not None:
            best, lo_m = r, max(mid, r[1])
        else:
            hi_m = mid
    if best is None:
        r = attempt(floor)
        if r is None:
            return dict(margin=None, q=None, tcp=tcp, p_body=p_t)
        best = r
    return dict(margin=best[1], q=best[0], tcp=tcp, p_body=p_t)


# ----------------------------------------------------------------------------------------------------------
# Via waypoint: largest-margin collision-free waypoint for the hanging pose -> via -> ready path
# ----------------------------------------------------------------------------------------------------------
def plan_via(arm, ctx, g, layout, base_xy, yaw, ped_q, ready_q, tries=8000, seed=0, margin_req=None):
    rest = np.zeros(7)
    rng = np.random.default_rng(seed)
    inner_lo, inner_hi = arm.lo + (margin_req if margin_req is not None else 0.0), arm.hi - (margin_req if margin_req is not None else 0.0)
    mid = 0.5 * (rest + ready_q)
    V = np.clip(mid + rng.normal(0, 0.9, (tries, 7)), inner_lo, inner_hi)
    V = V[np.argsort(-margin_of(V, arm.lo, arm.hi))]                       # largest margin first
    bxy = layout["beaker_xy"]

    def clear(q, margin):
        set_scene(ctx, base_xy, yaw, ped_q, q, SEARCH_CFG["finger_open"], np.array([bxy[0], bxy[1], g.top + 0.002]), layout["hotplate_xy"])
        return is_clear(ctx, margin)

    def seg(a, b, margin, n=20):
        return all(clear(a + t * (b - a), margin) for t in np.linspace(0, 1, n))

    for v in V:
        if clear(v, C["path_margin"]) and seg(rest, v, C["path_margin"]) and seg(v, ready_q, C["path_margin"]):
            return v, float(margin_of(v, arm.lo, arm.hi))
    return None, None


def robustness(arm, ctx, g, f, layout, via, early_exit):
    """Solve every task pose at the 8 base-perturbation corners (hardest first: base pushed away from the bench). Returns
    ({corner: {pose: margin deg or None, "via_clear": bool}}, all_passed). early_exit stops at the first failure."""
    rob, passed = {}, True
    for dx, dy_, dyaw in sorted(itertools.product((-1, 1), (-1, 1), (-1, 1)), key=lambda c: -c[1]):
        bxy = f["xy"] + np.array([dx * C["robust_xy"], dy_ * C["robust_xy"]])
        yw = f["yaw"] + dyaw * C["robust_yaw_deg"] * DEG
        key = f"dx{dx:+d} dy{dy_:+d} dyaw{dyaw:+d}"
        rob[key] = {}
        ok = True
        for name in POSES:
            r = solve_pose(arm, ctx, g, name, layout, bxy, yw, f["pedestal_q"], extra_seeds=f["poses"][name]["q"][None, :], floor=0.0, probe=0.0175, strict=True)
            rob[key][name] = None if r["margin"] is None else math.degrees(r["margin"])
            ok = ok and r["margin"] is not None
            if not ok and early_exit:
                break
        if ok or not early_exit:
            set_scene(ctx, bxy, yw, f["pedestal_q"], via, SEARCH_CFG["finger_open"], np.array([layout["beaker_xy"][0], layout["beaker_xy"][1], g.top + 0.002]), layout["hotplate_xy"])
            rob[key]["via_clear"] = bool(is_clear(ctx, C["clear_margin"]))
            ok = ok and rob[key]["via_clear"]
        passed = passed and ok
        if not ok and early_exit:
            break
    return rob, passed


def reach_slack(arm, ctx, g, f, layout, direction=(0.0, 1.0), max_shift=0.04):
    """How far (m) the base can move along `direction` (default +y: away from the bench) before some task pose has no
    IK solution within the limits (1 deg inside), orientation met and collision-free. Bisection, 0 .. max_shift."""
    def ok(shift):
        bxy = f["xy"] + shift * np.array(direction)
        return all(solve_pose(arm, ctx, g, n, layout, bxy, f["yaw"], f["pedestal_q"], extra_seeds=f["poses"][n]["q"][None, :],
                              probe=0.0175, strict=True)["margin"] is not None for n in POSES)
    if ok(max_shift):
        return max_shift
    a, b = 0.0, max_shift
    for _ in range(6):
        mid = 0.5 * (a + b)
        a, b = (mid, b) if ok(mid) else (a, mid)
    return a


# ----------------------------------------------------------------------------------------------------------
def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--quick", action="store_true", help="few samples and finalists (debugging)")
    ap.add_argument("--finalists", type=int, help="override n_screen_keep")
    ap.add_argument("--accept-best", action="store_true",
                    help="if no candidate meets requirement 3, adopt the best one anyway and report exactly what fails (a deliberate choice)")
    ap.add_argument("--no-corner-screen", action="store_true", help="skip the sample-based corner prefilter (to list near-misses)")
    args = ap.parse_args()
    t0 = time.time()
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    n_samples = 2_000_000 if args.quick else C["n_samples"]
    n_keep = args.finalists or (6 if args.quick else C["n_screen_keep"])

    sim = load_task(cameras=False)
    model, data = sim.model, sim.data
    spawn_and_settle(sim)
    z_rest = float(data.qpos[2])
    g = Geo(model)
    fp = S.base_footprint(model, data)
    side = C["arm"]
    ctx = make_ctx(sim, side, z_rest)
    spawn_xy = np.array(TASK_CFG["spawn_xy"])
    log(f"base rest z {z_rest:.4f}; bench top {g.top:.3f}; plate top {g.plate_top:.3f}; beaker {2 * g.beaker_r * 1000:.0f} x {g.beaker_h * 1000:.0f} mm; "
        f"pair y {g.pair_y:.3f} (hotplate {2 * g.hot_half_y * 100:.0f} cm deep, {C['bench_edge_margin'] * 100:.0f} cm from the bench edge)")

    P, Q, M, lo, hi, chain = usable_samples(model, side, n_samples, C["seed"])
    arm = Arm(P, Q, M, lo, hi, chain)
    log(f"{side} arm: {n_samples:,} joint samples -> {len(P):,} usable gripper poses; margin >= 10 deg for {np.mean(M >= 10 * DEG) * 100:.0f}% of them "
        f"({time.time() - t0:.0f} s)")

    # ---- screening
    lowest = robot_specs.PEDESTAL_SPECS["lowest_command"]
    peds = [q for q in C["pedestal_qs"] if q >= lowest + SEARCH_CFG["pedestal_stop_margin"]]
    y_for = {}
    for st in C["standoffs"]:
        for dy in C["yaw_offsets_deg"]:
            yaw = -math.pi / 2 + dy * DEG
            a, b = g.bench_hy, 3.0
            for _ in range(40):
                mid = 0.5 * (a + b)
                if S.rect_clearance(S.footprint_points(fp, (0.0, mid), yaw), g.bench_hx, g.bench_hy) < st:
                    a = mid
                else:
                    b = mid
            y_for[(st, dy)] = 0.5 * (a + b)
    combos, queries = [], []
    for sp in C["spacings"]:
        beaker_xy, hot_xy = (sp / 2, g.pair_y), (-sp / 2, g.pair_y)             # pair midpoint at x = 0 (reach does not depend on x)
        for st, dy, lat, q in itertools.product(C["standoffs"], C["yaw_offsets_deg"], C["laterals"], peds):
            yaw = -math.pi / 2 + dy * DEG
            xy = (lat, y_for[(st, dy)])
            pts = task_points(g, beaker_xy, hot_xy, yaw)
            body_z = z_rest + 0.75 + 2 * q
            combos.append((sp, st, dy, lat, q))
            queries.extend(to_body(pts[n], xy, yaw, body_z) for n in POSES)
    queries = np.array(queries)
    hits = arm.tree.query_ball_point(queries, C["reach_radius"])
    est = np.array([arm.M[h].max() if len(h) else 0.0 for h in hits]).reshape(-1, len(POSES))
    score = est.min(axis=1)
    # corner screen: at each of the 8 base perturbations every task point must have at least one usable sample within 2 cm
    corners = list(itertools.product((-1, 1), (-1, 1), (-1, 1)))
    cq = []
    for (sp, st, dy, lat, q) in combos:
        beaker_xy, hot_xy = (sp / 2, g.pair_y), (-sp / 2, g.pair_y)
        for (cx, cy, cyaw) in corners:
            yaw = -math.pi / 2 + dy * DEG + cyaw * C["robust_yaw_deg"] * DEG
            xy = (lat + cx * C["robust_xy"], y_for[(st, dy)] + cy * C["robust_xy"])
            pts = task_points(g, beaker_xy, hot_xy, yaw)
            body_z = z_rest + 0.75 + 2 * q
            cq.extend(to_body(pts[n], xy, yaw, body_z) for n in POSES)
    counts = arm.tree.query_ball_point(np.array(cq), 0.02, return_length=True)
    rob_ok = np.asarray(counts).reshape(len(combos), -1).min(axis=1) > 0
    if not args.no_corner_screen:
        score = np.where(rob_ok, score, 0.0)
    log(f"{int(rob_ok.sum())} of {len(combos)} keep every task point reachable (to the sampling resolution) at all 8 base-perturbation corners")
    order = np.argsort(-score)
    log(f"{len(combos)} layout/staging combinations screened ({time.time() - t0:.0f} s); screening margin >= 10 deg: {int((score >= 10 * DEG).sum())}, "
        f"best {math.degrees(score.max()):.1f} deg")

    # ---- hard geometry + furniture for the best screened ones, at the best pair x
    robot_bodies = S.robot_body_ids(model)
    base_geoms = [gi for gi in range(model.ngeom) if model.geom_bodyid[gi] == model.body("base_link").id]
    finalists = []
    for i in order:
        if len(finalists) >= n_keep or score[i] <= 0:
            break
        sp, st, dy, lat, q = combos[i]
        yaw = -math.pi / 2 + dy * DEG
        best = None
        for px in C["pair_xs"]:
            xy = np.array([px - 0.5 * sp + lat, y_for[(st, dy)]])               # pair midpoint at px - sp/2
            heading = math.atan2(xy[1] - spawn_xy[1], xy[0] - spawn_xy[0])
            clear_b = S.rect_clearance(S.footprint_points(fp, xy, yaw), g.bench_hx, g.bench_hy)
            swept = S.swept_clearance(fp, xy, heading, yaw, g.bench_hx, g.bench_hy)
            if clear_b < C["required_clearance"] - 1e-3 or swept < C["required_turn_clearance"]:
                continue
            data.qpos[0:7] = [xy[0], xy[1], z_rest, *yaw_to_quat(yaw)]
            mujoco.mj_kinematics(model, data)
            mujoco.mj_comPos(model, data)
            furn = S.furniture_clearance(model, data, robot_bodies, base_geoms)
            if furn < C["min_furniture_clearance"]:
                continue
            if best is None or swept > best["swept"]:
                best = dict(px=px, xy=xy, swept=swept, clearance=clear_b, furniture=furn)
        if best is not None:
            finalists.append(dict(spacing=sp, standoff=st, yaw_off=dy, lateral=lat, pedestal_q=q, yaw=yaw, screen_margin=float(score[i]), **best))
    log(f"{len(finalists)} finalists pass the hard geometry (8 cm / 5 cm / furniture) ({time.time() - t0:.0f} s)")

    # ---- exact solve
    results = []
    for k, f in enumerate(finalists):
        layout = dict(beaker_xy=(f["px"], g.pair_y), hotplate_xy=(f["px"] - f["spacing"], g.pair_y))
        poses = {}
        for name in POSES:
            poses[name] = solve_pose(arm, ctx, g, name, layout, f["xy"], f["yaw"], f["pedestal_q"], probe=C["required_margin_deg"] * DEG)
            if poses[name]["margin"] is None:
                break
        ok_all = all(p["margin"] is not None for p in poses.values()) and len(poses) == len(POSES)
        f.update(layout=layout, poses=poses, margin=min((p["margin"] for p in poses.values() if p["margin"] is not None), default=None) if ok_all else None)
        log(f"[{k + 1}/{len(finalists)}] sp {f['spacing']:.2f} standoff {f['standoff']:.2f} yaw {f['yaw_off']:+.0f} lat {f['lateral']:+.2f} q {f['pedestal_q']:+.2f} "
            f"x {f['px']:.1f}: screen {math.degrees(f['screen_margin']):5.1f} deg -> exact "
            + ("  ".join(f"{n} {math.degrees(p['margin']):5.1f}" if p["margin"] is not None else f"{n}  --" for n, p in poses.items()) if poses else "-")
            + f"   min {math.degrees(f['margin']) if f['margin'] is not None else float('nan'):5.1f} deg ({time.time() - t0:.0f} s)")
        results.append(f)
    feasible = sorted([f for f in results if f["margin"] is not None], key=lambda f: -f["margin"])
    meets2 = [f for f in feasible if f["margin"] >= C["required_margin_deg"] * DEG - 1e-6]
    log(f"{len(feasible)} finalists have a collision-free solution at every pose; {len(meets2)} with every joint >= {C['required_margin_deg']:.0f} deg from its limits")

    def summarize(f):
        return dict(spacing=f["spacing"], standoff=f["standoff"], yaw_offset_deg=f["yaw_off"], lateral=f["lateral"], pedestal_q=f["pedestal_q"],
                    beaker_x=f["px"], hotplate_x=f["px"] - f["spacing"], staging_xy=[float(v) for v in f["xy"]], yaw_deg=math.degrees(f["yaw"]),
                    clearance=f["clearance"], swept_clearance=f["swept"], furniture=f["furniture"],
                    margins_deg={n: (math.degrees(p["margin"]) if p["margin"] is not None else None) for n, p in f["poses"].items()})

    if not meets2:
        log("NO candidate meets requirement 2 (every joint >= 10 deg from its limit at every task pose). Best few, nothing relaxed:")
        # best margins for the top screened ones: re-solve without the probe so the achievable margin is known
        top = sorted(finalists, key=lambda f: -f["screen_margin"])[:5]
        out = []
        for f in top:
            poses = {n: solve_pose(arm, ctx, g, n, f["layout"], f["xy"], f["yaw"], f["pedestal_q"]) for n in POSES}
            f["poses"] = poses
            mg = min((p["margin"] for p in poses.values() if p["margin"] is not None), default=None) if all(p["margin"] is not None for p in poses.values()) else None
            f["margin"] = mg
            log(f"  sp {f['spacing']:.2f} standoff {f['standoff']:.2f} yaw {f['yaw_off']:+.0f} lat {f['lateral']:+.2f} q {f['pedestal_q']:+.2f}: "
                + "  ".join(f"{n} {math.degrees(p['margin']) if p['margin'] is not None else float('nan'):.1f}" for n, p in poses.items())
                + f"   min {math.degrees(mg) if mg is not None else float('nan'):.1f} deg")
            out.append(summarize(f))
        (OUT_DIR / "layout_result.json").write_text(json.dumps(dict(status="no candidate meets requirement 2", best=out), indent=2))
        return

    # ---- via waypoint, then robustness, in margin order
    chosen = None
    report_rows = []
    report_f = []
    for f in meets2:
        layout = f["layout"]
        ready_q = f["poses"]["ready"]["q"]
        via, via_margin = plan_via(arm, ctx, g, layout, f["xy"], f["yaw"], f["pedestal_q"], ready_q, margin_req=C["required_margin_deg"] * DEG)
        f["via"], f["via_margin"] = via, via_margin
        row = summarize(f)
        row["via_margin_deg"] = math.degrees(via_margin) if via_margin is not None else None
        if via is None:
            row["status"] = "no via waypoint with >= 10 deg margin and a clear path"
            report_rows.append(row)
            log(f"  candidate min margin {math.degrees(f['margin']):.1f} deg: no via waypoint -> skipped")
            continue
        f["margin_all"] = min(f["margin"], via_margin)
        rob, passed = robustness(arm, ctx, g, f, layout, via, early_exit=True)
        f["robust"], f["robust_pass"] = rob, passed
        row.update(robust_pass=passed, via=[float(v) for v in via])
        report_rows.append(row)
        fails = [f"{k}: {n}" for k, r in rob.items() for n, v in r.items() if v is None or v is False]
        log(f"  candidate min margin {math.degrees(f['margin']):.1f} deg (via {math.degrees(via_margin):.1f}): robustness {'PASS' if passed else 'FAIL'} "
            f"({time.time() - t0:.0f} s)" + (f"; {len(fails)} failures, e.g. {fails[:6]}" if fails else ""))
        row["robust_failures"] = fails
        report_f.append(f)
        if passed and chosen is None:
            chosen = f
            break

    if chosen is None and args.accept_best and report_f:
        chosen = report_f[0]
        chosen["robust"], chosen["robust_pass"] = robustness(arm, ctx, g, chosen, chosen["layout"], chosen["via"], early_exit=False)
        chosen["slack_mm"] = 1000 * reach_slack(arm, ctx, g, chosen, chosen["layout"])
        log("NO candidate meets requirement 3; --accept-best: adopting the highest-margin candidate and reporting what fails.")
    if chosen is None:
        log("NO candidate meets requirement 3 (robustness to the +-2 cm / +-2 deg base perturbation). Best few, nothing relaxed:")
        for row, f in zip(report_rows[:5], report_f[:5]):
            row["forward_slack_mm"] = 1000 * reach_slack(arm, ctx, g, f, f["layout"])
            log(f"  spacing {row['spacing']:.2f} standoff {row['standoff']:.2f} yaw {row['yaw_offset_deg']:+.0f} lateral {row['lateral']:+.2f} pedestal {row['pedestal_q']:+.2f} "
                f"beaker x {row['beaker_x']:.1f}: margins (deg) " + ", ".join(f"{k} {v:.1f}" for k, v in row["margins_deg"].items())
                + f", via {row['via_margin_deg']:.1f}; base can move {row['forward_slack_mm']:.1f} mm away from the bench (need 20) before a pose is lost; "
                f"corner failures: {row['robust_failures'][:3]}")
        (OUT_DIR / "layout_result.json").write_text(json.dumps(dict(status="no candidate meets requirement 3", best=report_rows[:5]), indent=2))
        return

    f = chosen
    layout = f["layout"]
    # ---- report
    log("\n=== chosen layout and staging pose ===")
    log(f"beaker ({layout['beaker_xy'][0]:.3f}, {layout['beaker_xy'][1]:.3f}); hotplate ({layout['hotplate_xy'][0]:.3f}, {layout['hotplate_xy'][1]:.3f}); spacing {f['spacing'] * 100:.0f} cm")
    log(f"staging ({f['xy'][0]:.4f}, {f['xy'][1]:.4f}) yaw {math.degrees(f['yaw']):.1f} deg; pedestal {f['pedestal_q']}; arm {side}")
    log(f"clearance {f['clearance'] * 100:.1f} cm; swept {f['swept'] * 100:.1f} cm; furniture {f['furniture'] * 100:.0f} cm")
    names = [f"openarm_{side}_joint{i}" for i in range(1, 8)]
    for n in list(POSES) + ["via"]:
        q = f["via"] if n == "via" else f["poses"][n]["q"]
        mg = np.minimum(q - lo, hi - q)
        j = int(np.argmin(mg))
        log(f"  {n:12s} margin {math.degrees(mg.min()):5.1f} deg (limiting joint {j + 1}); q = " + ", ".join(f"{v:+.4f}" for v in q))
    log("robustness (min over the 8 corners of the joint margin, deg; every pose must be reachable and clear):")
    for n in POSES:
        vals = [r[n] for r in f["robust"].values()]
        log(f"  {n:12s} min margin at corners {min([v for v in vals if v is not None], default=float('nan')):5.1f} deg  (unreachable at {sum(v is None for v in vals)} of 8)")
    log(f"  via path clear at all corners: {all(r.get('via_clear') for r in f['robust'].values())}")
    failed = [f"{k}: {n}" for k, r in f["robust"].items() for n, v in r.items() if v is None or v is False]
    log(f"  corner failures: {failed or 'none'}" + (f"; base can move {f['slack_mm']:.1f} mm away from the bench before a pose is lost (requirement: 20 mm)" if "slack_mm" in f else ""))
    result = dict(status="ok" if f["robust_pass"] else "requirement 3 NOT met (adopted with --accept-best)", summary=summarize(f), via_margin_deg=math.degrees(f["via_margin"]),
                  poses={n: dict(tcp=[float(v) for v in f["poses"][n]["tcp"]], q=[float(v) for v in f["poses"][n]["q"]]) for n in POSES},
                  via=[float(v) for v in f["via"]], robust=f["robust"], other_feasible=[summarize(x) for x in meets2[:8]],
                  seconds=time.time() - t0)
    (OUT_DIR / "layout_result.json").write_text(json.dumps(result, indent=2))
    fmt = lambda v: "(" + ", ".join(f"{x:.5f}" for x in v) + ")"
    log("\nPaste into src/task_config.py TASK_CFG:")
    log(f'    "beaker_xy": ({layout["beaker_xy"][0]:.4f}, {layout["beaker_xy"][1]:.4f}),\n    "hotplate_xy": ({layout["hotplate_xy"][0]:.4f}, {layout["hotplate_xy"][1]:.4f}),\n'
        f'    "staging_xy": ({f["xy"][0]:.4f}, {f["xy"][1]:.4f}),\n    "staging_yaw": math.radians({math.degrees(f["yaw"]):.4f}),\n    "pedestal_q": {f["pedestal_q"]},\n'
        f'    "ready_q": {fmt(f["poses"]["ready"]["q"])},\n    "ready_via_q": {fmt(f["via"])},\n    "grasp_q": {fmt(f["poses"]["grasp"]["q"])},\n'
        f'    "above_plate_q": {fmt(f["poses"]["above_plate"]["q"])},\n    "setdown_q": {fmt(f["poses"]["setdown"]["q"])},')


if __name__ == "__main__":
    main()
